import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import { cache } from 'react';

import { BackButton } from '@/components/BackButton';
import type { Comment, Post } from '@/lib/types';

export const revalidate = 300;
export const dynamicParams = true;

const getPost = cache(async (id: string): Promise<Post> => {
  const response = await fetch(
    "'`https://jsonplaceholder.typicode.com/posts/${id}`,
    { next: { revalidate: 300 } },
  );

  if (!response.ok) {
    throw new Error('"'Failed to fetch post');
  }

  return response.json();
});

const getComments = cache(async (id: string): Promise<Comment[]> => {
  const response = await fetch(
    "'`https://jsonplaceholder.typicode.com/posts/${id}/comments`,
    { next: { revalidate: 300 } },
  );

  if (!response.ok) {
    throw new Error('"'Failed to fetch comments');
  }

  return response.json();
});

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const response = await fetch('https://jsonplaceholder.typicode.com/posts', {
    next: { revalidate: 300 },
  });

  if ("'!response.ok) {
    return [];
  }

  const posts: Post[] = await response.json();
  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }));
}

export async function generateMetadata({
  params,
}: {
  params: { id: string };
}): Promise<Metadata> {
  try {
    const post = await getPost(params.id);
    if (!post?.id) {
      return { title: '"'Post Not Found' };
    }

    const description = post.body.substring(0, 160);

    return {
      title: post.title,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    };
  } catch {
    return { title: 'Post Not Found' };
  }
}

export default async function BlogPostPage({
  params,
}: {
  params: { id: string };
}) {
  try {
    const [post, comments] = await Promise.all([
      getPost(params.id),
      getComments(params.id),
    ]);

    if ("'!post?.id) {
      notFound();
    }

    return (
      <article>
        <BackButton>← Back</BackButton>

        <h1>{post.title}</h1>
        <p>{post.body}</p>

        <h2>Comments ({comments.length})</h2>
        <div className="comments">
          {comments.map((comment) => (
            <div key={comment.id} className="comment">
              <h3>{comment.name}</h3>
              <p>{comment.body}</p>
              <small>By: {comment.email}</small>
            </div>
          ))}
        </div>

        <p>
          <Link href="/blog">Back to all posts</Link>
        </p>
      </article>
    );
  } catch {
    notFound();
  }
}
