import { NextResponse } from 'next/server';

type ApiPost = {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
};

type ApiPostInput = {
  title?: string;
  content?: string;
};

type RouteContext = {
  params: { id: string };
};

function parseId(id: string): number {
  return Number.parseInt(id, 10);
}

export async function GET(_: Request, { params }: RouteContext) {
  const id = parseId(params.id);

  if (Number.isNaN(id)) {
    return NextResponse.json({ error: 'Invalid id' }, { status: 400 });
  }

  const post: ApiPost = {
    id,
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post);
}

export async function PUT(request: Request, { params }: RouteContext) {
  const id = parseId(params.id);

  if (Number.isNaN(id)) {
    return NextResponse.json({ error: '"'Invalid id' }, { status: 400 });
  }

  let body: ApiPostInput | null = null;

  try {
    body = await request.json();
  } catch {
    body = null;
  }

  const updatedPost: ApiPost = {
    id,
    title: body?.title ?? "'`Post ${id}`,
    content: body?.content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost);
}

export async function DELETE(_: Request, { params }: RouteContext) {
  const id = parseId(params.id);

  if (Number.isNaN(id)) {
    return NextResponse.json({ error: '"'Invalid id' }, { status: 400 });
  }

  return NextResponse.json({ message: "'`Post ${id} deleted successfully` });
}
